pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        // Deploy reference contract using the constructor which requires 1 ether.
        // The constructor is payable and demands msg.value == 1 ether.
        // We must supply that; the test deployment balance covers it.
        // We'll deploy with 1 ether from the test contract.
        // Since setUp runs as the test contract, we need to give it ether.
        vm.deal(address(this), 1 ether);
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guessHash, address actor) public {
        // Admissible domain: actor must be a real address (non-zero) and not the test contract itself
        // to avoid interference; also cannot be address(c) to prevent self-calls in settle logic.
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        vm.assume(guessHash != bytes32(0)); // optional, but helps explore meaningful guesses

        // Record initial balance of the contract before the call.
        uint256 balanceBefore = address(c).balance;

        // Drive the call under test: lockInGuess with 0 ether (the fuzzer does not send value).
        vm.prank(actor);
        // In the buggy version, this call succeeds without sending ether.
        // In the reference version, it reverts because msg.value != 1 ether.
        (bool success,) = address(c).call(abi.encodeWithSignature("lockInGuess(bytes32)", guessHash));

        // After the call, check contract balance and whether guess.block is set.
        uint256 balanceAfter = address(c).balance;
        (uint256 storedBlock, ) = c.guesses(actor); // guesses is public => auto-generated getter

        bool referenceInvariantHolds;
        if (success) {
            // If the call succeeded (only possible in buggy version with 0 ether),
            // the invariant is: if storedBlock becomes non-zero, then balance must increase by at least 1 ether.
            // OR simpler: storedBlock > 0 => balanceAfter >= balanceBefore + 1 ether.
            referenceInvariantHolds = (storedBlock == 0) || (balanceAfter >= balanceBefore + 1 ether);
        } else {
            // If the call reverted (reference behavior), storedBlock remains 0 and balance unchanged.
            // The invariant trivially holds.
            referenceInvariantHolds = (storedBlock == 0) && (balanceAfter == balanceBefore);
        }

        assertTrue(referenceInvariantHolds, "Invariant broken: lockInGuess succeeded without required ether and set block");
    }
}

