pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // fund C with initial 1 ether required by constructor
        vm.deal(address(this), 1 ether);
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(bytes32 hash, bool settleAfter) public {
        // ensure we have enough ether for the lockInGuess call
        vm.deal(address(this), 1 ether);

        // lock in a guess
        c.lockInGuess{value: 1 ether}(hash);

        // The reference ensures that after lockInGuess, the caller's stored block is non-zero (> current block.number).
        // The mutant leaves block = 0, making settle revert for 'block.number > 0' but then blockhash(0) returns 0x0,
        // so both answer != 0 and guesses[msg.sender].guess == answer may hold. With block = 0 in mutant, settle can
        // transfer 2 ether. On reference, block > current block, settle reverts due to 'block.number > guesses[msg.sender].block'.

        bool settlementSucceeds = true;
        if (settleAfter) {
            // advance at least one block so the condition block.number > storedBlock is satisfied for the reference
            vm.roll(block.number + 2);

            // On reference, settlement should revert because storedBlock > current block at time of call.
            // We wrap the settle call to see if it succeeds (no revert).
            try c.settle() {
                settlementSucceeds = true;
            } catch {
                settlementSucceeds = false;
            }
        }

        // property: if we settle after lockInGuess, the reference MUST revert (settlementSucceeds == false)
        // the mutant will NOT revert and settlementSucceeds will be true.
        assertTrue(!settlementSucceeds || !settleAfter);
    }
}

