pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Pseudo-randomly derive two actors from the seed
        address actor1 = address(uint160(uint256(keccak256(abi.encode(seed, 1)))));
        address actor2 = address(uint160(uint256(keccak256(abi.encode(seed, 2)))));
        // Avoid the zero address and the contract itself
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != address(c) && actor2 != address(c));
        vm.assume(actor1 != actor2);

        // We need to guarantee that both actors can lock at least once, so we supply each with 2 ether.
        // The constructor requires exactly 1 ether, so deploy with 1 ether and later send more if needed.
        // Actually we'll just deal enough ether for the whole test.
        vm.deal(actor1, 4 ether);
        vm.deal(actor2, 4 ether);

        // Random guess hash
        bytes32 guessHash = bytes32(seed);
        // We'll use blockhash of block.number + 1, which will be valid if we mine enough blocks later.

        // Actor1 locks in guess
        vm.prank(actor1);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Actor2 also locks in the same guess (or different – doesn't matter)
        vm.prank(actor2);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Warp to a block where blockhash(actor1's lock block) is valid (if we mine enough, up to 256 blocks later)
        // The fuzzer seed influences how many blocks we advance; we ensure it's within the 256-block window.
        uint256 advance = bound(seed, 2, 256);
        vm.roll(block.number + advance);

        // Record balances before settle
        uint256 balanceCBefore = address(c).balance;
        uint256 balanceActor1Before = actor1.balance;
        uint256 balanceActor2Before = actor2.balance;

        // Actor1 settles – we expect to succeed if blockhash is non-zero and guess matches.
        vm.prank(actor1);
        c.settle();

        // Actor2 settles similarly
        vm.prank(actor2);
        c.settle();

        uint256 balanceCAfter = address(c).balance;
        uint256 balanceActor1After = actor1.balance;
        uint256 balanceActor2After = actor2.balance;

        // invariants:
        // Each successful settle should pay out exactly 2 ether in the reference implementation.
        // Since both actors locked 1 ether each, the net effect is that the contract should have paid
        // 2 ether to each successful settler. If both succeed, the contract balance after should be
        // initial contract balance (with 1 ether from constructor) + 2 ether from lockIns – 4 ether payouts = -1 ether?
        // Wait, constructor requires msg.value == 1 ether, so the contract starts with 1 ether.
        // Each lockIn requires 1 ether, so after two lockIns the contract balance is 1 + 2 = 3 ether.
        // Two successful settles should pay 2 ether each = 4 ether total, but that's impossible because balance is only 3 ether.
        // Actually the contract won't be able to pay both 2 ether; the second settle will revert due to insufficient balance.
        // That's fine: we just care about the ones that succeed. So we must observe the actual net flow.
        // General rule: for every successful settle, the actor's balance increases by exactly 2 ether (payout).
        // If the bug changes it to 1 ether, then for successful settles the increase will be 1 ether.
        // So we assert: if actor1's settle succeeded (balance increased), then the increase must be exactly 2 ether.
        // If the bug is present, this assertion will fail for the cases where the increase is 1 ether.
        // However, we need to check only for succeed cases: if the settle reverted, balance doesn't change.
        // We cannot use try/catch inside a single assertTrue easily, so we simply check that the net
        // difference for actor1 is either 0 (if failed) or 2 ether (if succeeded). But the bug changes to 1 ether,
        // so the difference can be 1 ether. So the invariant "difference is 0 or 2 ether" holds for reference but breaks for bug.
        // Actually if settle failed, difference = 0; if succeeded, ref: difference = 2 ether; bug: difference = 1 ether.
        // So the invariant "difference != 1 ether" would hold for ref and break for bug. But we want a positive assertion.
        // Let's use: (balanceActor1After - balanceActor1Before) % 1 ether == 0 and also check that if it's non-zero, it's exactly 2 ether.
        // Simpler: assert that the net change is either 0 or 2 ether. That's an exclusive range.
        // Since the fuzz may sometimes cause settle to fail (e.g., blockhash zero), difference is 0. In other cases it should be 2.
        // For the bug, sometimes it will be 1, violating the assertion.

        uint256 diff1 = balanceActor1After - balanceActor1Before;
        uint256 diff2 = balanceActor2After - balanceActor2Before;

        // The reference satisfies: diff1 == 0 || diff1 == 2 ether.
        // The bug produces diff1 == 1 ether for successful settles.
        // So we assert that for both actors, their ether change is either 0 or exactly 2 ether.
        assertTrue(
            (diff1 == 0 || diff1 == 2 ether) &&
            (diff2 == 0 || diff2 == 2 ether)
        );
    }
}

