pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess, uint256 blockOffset) public {
        // Ensure blockOffset is within the valid range for blockhash (last 256 blocks)
        bound(blockOffset, 1, 256);
        vm.assume(blockOffset <= block.number);

        // Setup: fund the contract with exactly 1 ether via lockInGuess
        address actor = address(0x1234);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // Prepare the block for which the guess should be correct
        uint256 targetBlock = block.number + blockOffset;
        vm.roll(targetBlock);
        // Warp to a block after the target block so settle condition passes
        vm.roll(targetBlock + 1);

        // Record actor's balance before settle
        uint256 balanceBefore = actor.balance;

        // Perform settle as the actor
        vm.prank(actor);
        try c.settle() {} catch {}

        // After settle, check that if the guess was correct and blockhash is non-zero,
        // the actor received exactly 2 ether. Otherwise, the actor's balance remains unchanged.
        bytes32 answer = blockhash(targetBlock);
        bool correctGuess = (answer != 0 && guess == answer);

        if (correctGuess) {
            assertTrue(actor.balance == balanceBefore + 2 ether);
        } else {
            assertTrue(actor.balance == balanceBefore);
        }
    }
}

