pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint256 beneficiaryPriv) public {
        // Ensure the private key maps to a valid Ethereum address
        address beneficiary = vm.addr(beneficiaryPriv);
        vm.assume(beneficiary != address(0));
        vm.assume(beneficiary != address(this));
        vm.assume(beneficiary != address(c));

        // Fund beneficiary for lockInGuess
        vm.deal(beneficiary, 2 ether);

        // Step 1: lock in a guess
        vm.prank(beneficiary);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Step 2: advance blocks to make block.number > lock block, and manipulate blockhash
        // The lock block is block.number after the lockInGuess call. We need to be past it.
        uint256 lockBlock = block.number;
        // Advance many blocks forward to ensure we are beyond lockBlock and the blockhash for lockBlock is zero (impossible to match)
        // or use vm.roll to set a specific block and vm.warp to set a specific timestamp, but we cannot set blockhash.
        // The only way for settle to transfer is when blockhash(lockBlock) != 0 and matches guess.
        // Since blockhash is only available for the last 256 blocks, we need to be within that window.
        // To make the test general and let the fuzzer find a match, we need the guess to equal a blockhash
        // that the contract can actually access. We can roll to a block where blockhash(lockBlock) equals guessHash.
        // But the fuzzer provides guessHash, so we can set up the chain state so that blockhash(lockBlock) == guessHash.
        // This requires the test to manipulate blockhash, which is possible via vm.roll and vm.warp, but blockhash depends on the block number.
        // Actually, we can just use the fact that the blockhash for the current block number - 1 is accessible and is deterministic.
        // But we cannot control it easily. Alternatively, we can accept that many fuzz runs will fail the require(block.number > guesses[msg.sender].block)
        // if we don't advance blocks. So we advance blocks unconditionally.
        vm.roll(lockBlock + 2);

        // Record contract balance before settle
        uint256 balanceBefore = address(c).balance;

        // Step 3: attempt settle as beneficiary
        vm.prank(beneficiary);
        // The call may fail if answer is zero or guess mismatch. We handle that.
        (bool success, ) = address(c).call(abi.encodeWithSignature("settle()"));

        // If settle succeeded and the transfer happened (answer != 0 && guess == answer),
        // the contract balance should decrease by exactly 2 ether.
        // If it failed, balance should remain unchanged. So we cannot unconditionally assert the decrease.
        // We need to detect if transfer happened.
        // According to the logic, transfer happens when answer != 0 && guesses[msg.sender].guess == answer.
        // We can check if the guess matched a non-zero blockhash. But in the test, we rolled to lockBlock+2,
        // so blockhash(lockBlock) is accessible only if lockBlock is within 256 blocks of current block.
        // This is true because we just rolled to +2.
        bytes32 answer = blockhash(lockBlock);
        bool transferExpected = (answer != 0 && answer == guessHash);

        if (success && transferExpected) {
            // The contract should have paid 2 ether to beneficiary.
            // Therefore its balance should decrease by exactly 2 ether.
            // Buggy version pays only 1 ether, so balance decreases by only 1 ether.
            assertEq(address(c).balance, balanceBefore - 2 ether, "Contract balance decreased incorrectly");
        }
    }
}

