import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 randomBlock) public {
        // randomBlock will be used as the block number for the guess, bounded to be in the past
        vm.assume(randomBlock > 0 && randomBlock < block.number);

        // create a guess that matches the blockhash of randomBlock
        bytes32 answer = blockhash(randomBlock);
        vm.assume(answer != 0);

        // deploy a guesser and fund the contract
        address guesser = address(0x1234);
        vm.deal(guesser, 2 ether);
        vm.startPrank(guesser);
        c.lockInGuess{value: 1 ether}(answer);
        vm.stopPrank();

        // advance blocks to make the guess settleable
        vm.roll(randomBlock + 2);

        uint256 balanceBefore = address(c).balance;
        vm.prank(guesser);
