        uint256 balanceAfter = address(c).balance;

        // Assert: balance strictly decreased (transfer of 2 ether in reference) vs. unchanged in buggy.
        // The reference should have balanceAfter = balanceBefore - 2 ether.
        // The buggy should have balanceAfter = balanceBefore.
        // So for reference, balanceAfter < balanceBefore; for buggy, balanceAfter == balanceBefore.
        // The rule: balanceAfter < balanceBefore.
        // This holds for reference (correct guess => transfer), but fails for buggy (no transfer).
        assertTrue(balanceAfter < balanceBefore);
    }
}

