import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 blockDelta, bytes32 guessHash) public {
        // Bound blockDelta to a small enough range that we stay within reachable block numbers
        uint256 boundedDelta = bound(blockDelta, 1, 256);
        address alice = address(0x1000);
        vm.deal(alice, 2 ether);

        // Lock in a guess from alice
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance past the lock-in block
        vm.roll(block.number + boundedDelta);

        // Record balance before settle
        uint256 balBefore = alice.balance;
        try c.settle() returns (bool) {
            // settle did not revert
            uint256 balAfter = alice.balance;
            // If answer != 0 and guess matches, alice should have received 2 ether
            // The reference uses blockhash(guesses[alice].block), which may be 0 or matching;
            // the mutant uses blockhash(block.number), which is always 0 within 256 blocks.
            // General rule: If settle succeeds without revert, any successful payout (balance increase by 2 ether)
            // only happens when the stored guess matches the blockhash of the stored block.
            // The mutant cannot pay out because it always uses a zero blockhash, so this assertion
            // holds trivially for the mutant (never pays out), but the reference may pay out when guess matches.
            // Actually we need a rule that the reference satisfies and the mutant breaks.
            // New rule: When the guess matches the blockhash of the block recorded at lock-in,
            // and that blockhash is non-zero, alice receives 2 ether.
            if (balAfter == balBefore + 2 ether) {
                // Payout happened. This must have required guessHash == blockhash(block.number - boundedDelta)
                // (the block recorded in guesses). The reference will pay iff guess matches;
                // the mutant will never pay (uses current blockhash = 0), so if we force a match,
                // reference pays, mutant doesn't. We check correctness of the payout condition.
                bytes32 expectedHash = blockhash(block.number - boundedDelta);
                assertTrue(guessHash == expectedHash && expectedHash != bytes32(0));
            }
        } catch {
            // settle reverted, nothing to assert further
        }
    }
}

