pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guessHash, uint256 blockDelay) public {
        // Admissible domain: delay at least 1 block after lock-in so settle() passes the block.number > ... check
        blockDelay = bound(blockDelay, 1, 256);

        address actor = address(0x1234);

        // Give actor exactly 1 ether to lock in a guess
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance chain state to the recorded block + blockDelay
        uint256 targetBlock = block.number + blockDelay;
        vm.roll(targetBlock);
        // We stay within the reachable blockhash window (last 256 blocks)
        // to ensure answer is non-zero.

        // Record balance before settle
        uint256 balanceBefore = actor.balance;

        vm.prank(actor);
        c.settle();

        uint256 balanceAfter = actor.balance;

        // The general rule: if the guess matches the blockhash of the recorded block,
        // the caller must receive exactly 2 ether. Otherwise, balance should be unchanged.
        // The buggy version always fails to match, so balance never changes.
        bytes32 correctAnswer = blockhash(block.number - blockDelay);
        if (correctAnswer != 0 && guessHash == correctAnswer) {
            assertTrue(balanceAfter == balanceBefore + 2 ether);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
